/* swish-heading-safety */
body :is(h1,h2,h3,h4,h5,h6),body [aria-hidden="true"][class*="ghost"]:is([class*="title"],[class*="heading"]){overflow-wrap:break-word;hyphens:auto;min-width:0;white-space:normal!important;text-wrap:balance}
body .sf-fit{display:block;white-space:normal!important;text-wrap:balance;overflow-wrap:break-word;hyphens:auto;min-width:0}body .sf-fit-95{zoom:0.95}body .sf-fit-90{zoom:0.9}body .sf-fit-85{zoom:0.85}body .sf-fit-80{zoom:0.8}body .sf-fit-75{zoom:0.75}body .sf-fit-70{zoom:0.7}body .sf-fit-65{zoom:0.65}body .sf-fit-60{zoom:0.6}
@media (max-width:781px){body :is(h1,h2,h3,h4,h5,h6),body [aria-hidden="true"][class*="ghost"]:is([class*="title"],[class*="heading"]),body .sf-fit{overflow-wrap:anywhere}}

/* featured engagement card: keep the title clear of its flag */
.dk-model.is-featured h3{padding-right:6.5rem}
/* contact form block inside the glass card */
.dk-form .sfcore-swish-form,.dk-form .sfcore-swish-form__form{background:none;border:0;box-shadow:none;padding:0;margin:0;max-width:none}
.dk-form .sfcore-swish-form__fields{display:grid;grid-template-columns:1fr 1fr;gap:1rem;align-items:end}
.dk-form .sfcore-swish-form__field{margin:0;width:auto;max-width:none;flex:none;min-width:0}
.dk-form .sfcore-swish-form__field-error:empty{display:none}
.dk-form .sfcore-swish-form__field--full{grid-column:1/-1}
.dk-form .sfcore-swish-form__label{display:block;margin:0 0 .45rem;font-size:.82rem;font-weight:600;letter-spacing:0;text-transform:none;color:var(--dk-ink2)}
.dk-form .sfcore-swish-form__required{color:var(--dk-vio);margin-left:.2rem}
.dk-form .sfcore-swish-form__select{font:500 .98rem/1.4 var(--dk-font);color:var(--dk-ink);background-color:rgba(253,253,255,0.85);border:1px solid var(--dk-line);border-radius:18px;padding:.8rem .95rem;width:100%;box-sizing:border-box}
.dk-form .sfcore-swish-form__submit{margin-top:.4rem}
.dk-form .sfcore-swish-form__button{display:inline-flex;align-items:center;gap:.6rem;font:600 .95rem/1.2 var(--dk-font);letter-spacing:0;text-transform:none;color:#fdfdff;background:var(--dk-vio);border:0;border-radius:99px;padding:1rem 1.6rem;cursor:pointer;box-shadow:0 18px 40px -18px rgba(127,66,222,.55)}
.dk-form .sfcore-swish-form__button:hover{background:var(--dk-vio-d)}
@media (max-width:781px){.dk-form .sfcore-swish-form__fields{grid-template-columns:1fr}}

body :focus:not(:focus-visible){outline:none!important}body :where(a,button,summary,[tabindex],[role=button],input[type=checkbox],input[type=radio],input[type=submit],input[type=button]):focus-visible{outline:2px solid #2563EB!important;outline-offset:3px!important;box-shadow:0 0 0 3px #fff}body :where(input,textarea,select):focus-visible{outline-color:#2563EB}.wp-block-navigation .wp-block-navigation-item__content:focus-visible{outline-offset:4px!important}
